void ScriptSession::startAI(unsigned owner,const std::string& script,bool campaign){
    if(owner>=12 || !setupApplied_ || script.empty())throw std::runtime_error("AI startup requires an active player and a source script");if(ais_[owner])return;auto& resources=requireWorld().resources();std::vector<jass::Source> sources;
    for(auto path:{"Scripts\\common.j","Scripts\\common.ai"}){auto member=resources.readCandidates({path},ArchiveScope::Common);if(!member)throw std::runtime_error(std::string("Missing common AI source: ")+path);sources.push_back({path,sourceText(member->bytes),member->source});}
    auto member=resources.readCandidates({script,"Scripts\\"+script});if(!member){OutputDebugStringA(("MAP DESIGNER: AI script '"+script+"' not found!\n").c_str());return;}sources.push_back({script,sourceText(member->bytes),member->source});auto module=jass::Module::compile(jass::Program::parse(std::move(sources)));auto entry=module.functionId("main");if(entry==jass::none || module.program().functions()[entry].native || !module.functions()[entry].parameters.empty() || module.type(module.functions()[entry].result).name!="nothing")throw std::runtime_error("AI strategy requires main takes nothing returns nothing");
    auto ai=std::make_unique<ScriptAI>();ai->owner=owner;ai->file=script;ai->origin=member->source;ai->campaign=campaign;ai->runtime=std::make_unique<jass::Runtime>(std::move(module));ai->runtime->inheritNatives(runtime_);ai->runtime->shareThreads(runtime_);auto& state=*ai;ais_[owner]=std::move(ai);aiTowns(state);state.goal=state.stage=state.home;bindAiRuntime(state);bindAiGuardNatives(state);state.runtime->initialize();state.runtime->pauseThreads(aiPauseDepth_[owner]!=0);state.runtime->start("main");
}
void ScriptSession::bindAiNatives(){
    bindAiControlNatives();
    for(auto [name,campaign]:std::initializer_list<std::pair<const char*,bool>>{{"StartMeleeAI",false},{"StartCampaignAI",true}})bind(name,"nothing",{"player","string"},[this,campaign](auto& vm,auto args){if(!args[1].text)throw std::runtime_error("Null AI script");startAI(playerId(args[0]),*args[1].text,campaign);return vm.nothing();});
    bind("CommandAI","nothing",{"player","integer","integer"},[this](auto& vm,auto args){auto& ai=ais_[playerId(args[0])];if(!ai)return vm.nothing();if(ai->commands.size()>=1024)throw std::runtime_error("AI command queue exceeds budget");ai->commands.emplace_back(std::bit_cast<int>(args[1].bits),std::bit_cast<int>(args[2].bits));return vm.nothing();});
}
std::vector<std::uint32_t> ScriptSession::aiCaptain(ScriptAI& ai){std::vector<std::uint32_t> result;for(auto id:ai.captain)if(alive(id,NativeKind::Unit)){auto& u=*units_.at(id);if(u.owner==ai.owner && !u.removing && !u.hidden() && number(u.life)>0 && !ai.guardUnits.contains(id) && !ai.suicideUnits.contains(id) && (ai.groupTimedLife || !u.timedLife))result.push_back(id);}return result;}
std::uint32_t ScriptSession::aiEnemy(ScriptAI& ai,unsigned owner,bool buildings,std::optional<WorldPoint> center){
    auto origin=center.value_or(ai.home);std::uint32_t result=0;float best=FLT_MAX;for(auto& [id,u]:units_)if(u->owner!=ai.owner && (owner==UINT_MAX?u->owner<12:u->owner==owner) && !(config_.players[ai.owner].alliances[u->owner]&1) && !u->hidden() && !u->removing && number(u->life)>0 && !u->invulnerable && !unitInvisibleTo(id,ai.owner) && (!buildings || u->building)){float score=std::hypot(number(u->x)-number(origin.x),number(u->y)-number(origin.y));if(ai.policies[ScriptAI::TargetHeroes] && u->hero)score*=.75f;if(ai.policies[ScriptAI::WatchMega] && u->level>=10)score*=.75f;if(score<best){best=score;result=id;}}return result;
}
bool ScriptSession::aiEnemyBaseCandidate(const ScriptAI& ai,const UnitState& u){return u.owner<12 && u.owner!=ai.owner && !(config_.players[ai.owner].alliances[u.owner]&1) && !u.hidden() && !u.removing && number(u.life)>0 && !u.invulnerable && u.building && !unitInvisibleTo(u.handle,ai.owner);}
void ScriptSession::aiEnemyBaseSearchTick(ScriptAI& ai){
    if(!ai.enemyBaseSearch)return;auto& search=*ai.enemyBaseSearch;auto it=units_.upper_bound(search.cursor);unsigned checked=0;for(;it!=units_.end() && checked<64;++it,++checked){search.cursor=it->first;auto& u=*it->second;if(!aiEnemyBaseCandidate(ai,u))continue;float score=distance(u,ai.home);if(ai.policies[ScriptAI::TargetHeroes] && u.hero)score*=.75f;if(ai.policies[ScriptAI::WatchMega] && u.level>=10)score*=.75f;if(score<search.distance){search.distance=score;search.best=it->first;}}if(it!=units_.end())return;if(search.best && (!alive(search.best,NativeKind::Unit) || !aiEnemyBaseCandidate(ai,*units_.at(search.best)))){ai.enemyBaseSearch=AIEnemyBaseSearch{};return;}ai.enemyBase=search.best;ai.enemyBaseSearch.reset();
}
void ScriptSession::aiCancelCaptainRoute(ScriptAI& ai){if(ai.captainRouteTicket==UINT64_MAX)throw std::runtime_error("AI captain route ticket exhausted");++ai.captainRouteTicket;ai.captainRoute.reset();}
void ScriptSession::aiCaptainRouteTick(ScriptAI& ai){
    if(!ai.captainRoute)return;auto ticket=ai.captainRoute->ticket;auto members=ai.captainRoute->members;for(auto [id,index]:members){if(!ai.captainRoute || ai.captainRoute->ticket!=ticket)return;if(!alive(id,NativeKind::Unit) || !ai.captain.contains(id)){ai.captainRoute->members.erase(id);continue;}auto u=units_.at(id);if(u->owner!=ai.owner || u->removing || u->hidden() || u->transport || number(u->life)<=0 || pathMovement(u->movementType)!=PathMovement::Amphibious){ai.captainRoute->members.erase(id);continue;}if(u->paused || u->stunned() || u->cast || u->combat.target)continue;if(index>=ai.captainRoute->points.size()){ai.captainRoute->members.erase(id);continue;}auto point=ai.captainRoute->points[index];if(u->currentOrder && u->currentOrder!=851983){ai.captainRoute->members.erase(id);continue;}if(u->combat.attackMove && std::hypot(number(u->combat.attackMove->x)-number(point.x),number(u->combat.attackMove->y)-number(point.y))>std::max(48.f,u->collision)){ai.captainRoute->members.erase(id);continue;}if(distance(*u,point)>std::max(48.f,u->collision)){if(!u->combat.attackMove)ai.captainRoute->members.erase(id);continue;}if(index+1>=ai.captainRoute->points.size()){ai.captainRoute->members.erase(id);continue;}auto next=ai.captainRoute->points[index+1];ai.captainRoute->members[id]=index+1;bool accepted=attackMove(id,next);if(!ai.captainRoute || ai.captainRoute->ticket!=ticket)return;if(!accepted)ai.captainRoute->members.erase(id);}if(ai.captainRoute && ai.captainRoute->ticket==ticket && ai.captainRoute->members.empty())ai.captainRoute.reset();
}
void ScriptSession::aiAttack(ScriptAI& ai,WorldPoint point,std::uint32_t target){
    auto clamped=requireWorld().clamp(point);if(ai.zeppelinWave && (clamped.x.bits()!=ai.zeppelinWave->destination.x.bits() || clamped.y.bits()!=ai.zeppelinWave->destination.y.bits()))aiCancelZeppelinWave(ai);aiCancelCaptainRoute(ai);auto ticket=ai.captainRouteTicket;bool sameGoal=ai.goal.x.bits()==point.x.bits() && ai.goal.y.bits()==point.y.bits();ai.goal=point;ai.retreating=false;auto members=aiCaptain(ai);if(!ai.zeppelinWave && aiHasTransport(ai))for(auto id:members){auto u=units_.at(id);if((!ai.policies[ScriptAI::IgnoreInjured] || number(u->life)>=number(u->maxLife)*.5f) && aiCanTransportTo(ai,*u,clamped)){aiLoadZeppelinWave(ai,clamped,true);if(ai.captainRouteTicket!=ticket)return;break;}}if(ai.amphibious && !ai.pathingDisabled && !target)for(auto id:members){auto u=units_.at(id);if(ai.waveUnit(id) || pathMovement(u->movementType)!=PathMovement::Amphibious || (ai.policies[ScriptAI::IgnoreInjured] && number(u->life)<number(u->maxLife)*.5f))continue;auto points=requireWorld().route({u->x,u->y},clamped,0,PathMovement::Amphibious);if(!points.empty())ai.captainRoute=AICaptainRoute{ticket,std::move(points),{}};break;}
    for(auto id:members){if(ai.captainRouteTicket!=ticket)return;if(!alive(id,NativeKind::Unit) || ai.waveUnit(id))continue;auto u=units_.at(id);if(u->owner!=ai.owner || !ai.captain.contains(id) || (ai.policies[ScriptAI::IgnoreInjured] && number(u->life)<number(u->maxLife)*.5f))continue;if(target && alive(target,NativeKind::Unit)){auto chosen=target;if(ai.policies[ScriptAI::SmartArtillery] && !units_.at(target)->building && unitWeapon(*u,0).range>=600)if(auto building=aiEnemy(ai,units_.at(target)->owner,true))chosen=building;if(u->combat.target==chosen && !u->combat.attackAbility)continue;auto victim=units_.at(chosen);auto targetPoint=requireWorld().clamp({victim->x,victim->y});if(sameGoal && u->combat.attackMove && !u->combat.patrolStart && !u->combat.patrolEnd && std::hypot(number(u->combat.attackMove->x)-number(targetPoint.x),number(u->combat.attackMove->y)-number(targetPoint.y))<=128)continue;if(!victim->hidden() && !victim->removing && number(victim->life)>0 && !unitVisibleTo(chosen,u->owner) && !unitInvisibleTo(chosen,u->owner))attackMove(id,targetPoint);else attackUnit(id,chosen);}else if(ai.captainRoute && pathMovement(u->movementType)==PathMovement::Amphibious){auto waypoint=ai.captainRoute->points.front();ai.captainRoute->members[id]=0;bool accepted=attackMove(id,waypoint);if(ai.captainRouteTicket!=ticket)return;if(!accepted && ai.captainRoute)ai.captainRoute->members.erase(id);}else attackMove(id,point);}if(ai.captainRoute && ai.captainRoute->members.empty())ai.captainRoute.reset();
}
